\usetikzlibrary{calc,angles,arrows.meta}
\begin{tikzpicture}[draw=black,text=black,line width=0.8pt,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{regionArea}{HTML}{D4E8FF}
\coordinate (O) at (0,0);
\coordinate (A) at (165:2);
\coordinate (B) at (15:2);
\coordinate (P) at (165:3);
\coordinate (Q) at (15:3);
\path[fill=regionArea,draw=none] (Q) arc[start angle=15,end angle=165,radius=3] -- (A) arc[start angle=165,end angle=15,radius=2] -- cycle;
\draw (P) -- (O) -- (Q);
\draw (Q) arc[start angle=15,end angle=165,radius=3];
\draw (B) arc[start angle=15,end angle=165,radius=2];
\pic[draw=black,line width=0.4pt,angle radius=0.42cm] {angle=Q--O--P};
\node[above,inner sep=1pt] at (90:0.53) {$150^\circ$};
\coordinate (MA) at ($(O)!0.5!(A)$);
\coordinate (MB) at ($(O)!0.5!(B)$);
\draw[line width=0.4pt] ($(MA)!0.075cm!90:(A)$) -- ($(MA)!0.075cm!-90:(A)$);
\draw[line width=0.4pt] ($(MB)!0.075cm!90:(B)$) -- ($(MB)!0.075cm!-90:(B)$);
\foreach \t in {0.44,0.56} {
  \coordinate (ML) at ($(A)!\t!(P)$);
  \coordinate (MR) at ($(B)!\t!(Q)$);
  \draw[line width=0.4pt] ($(ML)!0.075cm!90:(P)$) -- ($(ML)!0.075cm!-90:(P)$);
  \draw[line width=0.4pt] ($(MR)!0.075cm!90:(Q)$) -- ($(MR)!0.075cm!-90:(Q)$);
}
\foreach \v in {O,A,B,P,Q} {\fill[black] (\v) circle[radius=0.035cm];}
\node[below,inner sep=2pt] at (O) {$O$};
\node[below,inner sep=2pt] at (A) {$A$};
\node[below,inner sep=2pt] at (B) {$B$};
\node[below left,inner sep=2pt] at (P) {$P$};
\node[below right,inner sep=2pt] at (Q) {$Q$};
\coordinate (Pd) at ($(P)+(255:0.42)$);
\coordinate (Ad) at ($(A)+(255:0.42)$);
\coordinate (Od) at ($(O)+(255:0.42)$);
\draw[line width=0.4pt,{Stealth[length=1.4mm]}-{Stealth[length=1.4mm]}] (Pd) -- node[midway,below,inner sep=1pt] {$4$} (Ad);
\draw[line width=0.4pt,{Stealth[length=1.4mm]}-{Stealth[length=1.4mm]}] (Ad) -- node[midway,below,inner sep=1pt] {$8$} (Od);
\draw[line width=0.4pt] ($(Pd)+(75:0.07)$) -- ($(Pd)+(255:0.07)$);
\draw[line width=0.4pt] ($(Ad)+(75:0.07)$) -- ($(Ad)+(255:0.07)$);
\draw[line width=0.4pt] ($(Od)+(75:0.07)$) -- ($(Od)+(255:0.07)$);
